CREATE TABLE offline_meta (id INTEGER PRIMARY KEY CHECK(id=1), epoch TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>=0), public_keys_json TEXT NOT NULL) STRICT;
CREATE TABLE offline_streams (stream_id TEXT PRIMARY KEY, device_id TEXT NOT NULL, subject_id TEXT NOT NULL, package_id TEXT NOT NULL, device_epoch INTEGER NOT NULL, user_epoch INTEGER NOT NULL, created_at INTEGER NOT NULL) STRICT;
CREATE TABLE offline_leases (lease_id TEXT PRIMARY KEY, device_id TEXT NOT NULL, request_id TEXT NOT NULL, fingerprint TEXT NOT NULL, stream_id TEXT NOT NULL REFERENCES offline_streams(stream_id), lease_json TEXT NOT NULL, UNIQUE(device_id,request_id)) STRICT;
CREATE TABLE offline_operations (operation_id TEXT PRIMARY KEY, stream_id TEXT NOT NULL REFERENCES offline_streams(stream_id), device_sequence INTEGER NOT NULL CHECK(device_sequence>0), order_id TEXT NOT NULL, owner_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('create','edit','append_note','set_state')), content_sha256 TEXT NOT NULL, operation_json TEXT NOT NULL, received_at INTEGER NOT NULL, previous_operation_id TEXT, UNIQUE(stream_id,device_sequence)) STRICT;
CREATE TABLE offline_states (operation_id TEXT PRIMARY KEY REFERENCES offline_operations(operation_id), state TEXT NOT NULL CHECK(state IN ('received','waiting_dependency','applied','conflict','rejected')), reason TEXT, applied_request_id TEXT REFERENCES requests(request_id), CHECK((state='applied')=(applied_request_id IS NOT NULL))) STRICT;
CREATE TABLE offline_events (sequence INTEGER PRIMARY KEY, operation_id TEXT NOT NULL REFERENCES offline_operations(operation_id), state TEXT NOT NULL, at INTEGER NOT NULL) STRICT;
CREATE TABLE offline_collisions (sequence INTEGER PRIMARY KEY, device_id TEXT NOT NULL, operation_id TEXT NOT NULL, content_sha256 TEXT NOT NULL, operation_json TEXT NOT NULL, received_at INTEGER NOT NULL, UNIQUE(device_id,operation_id,content_sha256)) STRICT;
CREATE TABLE offline_conflicts (operation_id TEXT PRIMARY KEY REFERENCES offline_operations(operation_id), base_json TEXT NOT NULL, current_json TEXT NOT NULL, candidate_json TEXT NOT NULL) STRICT;
CREATE TABLE offline_resolutions (operation_id TEXT PRIMARY KEY REFERENCES offline_conflicts(operation_id), resolution_operation_id TEXT NOT NULL UNIQUE REFERENCES offline_operations(operation_id), decision_json TEXT NOT NULL) STRICT;
CREATE TABLE order_changes_feed (change_id INTEGER PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(order_id), order_revision INTEGER NOT NULL, owner_id TEXT NOT NULL, created_at INTEGER NOT NULL) STRICT;
CREATE INDEX offline_ready ON offline_states(state,operation_id);
CREATE INDEX offline_order_chain ON offline_operations(order_id,received_at,operation_id);
CREATE INDEX offline_predecessor ON offline_operations(previous_operation_id);
CREATE TRIGGER offline_operations_no_update BEFORE UPDATE ON offline_operations BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER offline_operations_no_delete BEFORE DELETE ON offline_operations BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER offline_leases_no_update BEFORE UPDATE ON offline_leases BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER offline_leases_no_delete BEFORE DELETE ON offline_leases BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER offline_events_no_update BEFORE UPDATE ON offline_events BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER offline_events_no_delete BEFORE DELETE ON offline_events BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
